function normalize(){const s=readSpec();if(!originalFrames.length)throw Error('请先载入动作幀。');if(s.width*s.height*originalFrames.length>24_000_000)throw Error('画布总像素过大，手机建议 256 或 512 像素。');stopPlay();const boxes=originalFrames.map(boundingBox),valid=boxes.filter(Boolean),maxW=s.align?Math.max(1,...valid.map(b=>b.width)):Math.max(...originalFrames.map(f=>f.width)),maxH=s.align?Math.max(1,...valid.map(b=>b.height)):Math.max(...originalFrames.map(f=>f.height)),ratio=Math.min((s.width-(s.align?8:0))/maxW,(s.height-(s.align?8:0))/maxH);frames=originalFrames.map((f,i)=>{const cv=canvas(s.width,s.height);if(!boxes[i])return cv;const b=s.align?boxes[i]:{x:0,y:0,width:f.width,height:f.height},w=Math.max(1,Math.round(b.width*ratio)),h=Math.max(1,Math.round(b.height*ratio)),ctx=cv.getContext('2d');ctx.imageSmoothingEnabled=!s.pixel;ctx.drawImage(f,b.x,b.y,b.width,b.height,Math.floor((s.width-w)/2),s.align?s.height-4-h:Math.floor((s.height-h)/2),w,h);return cv;});frameIndex=0;render();toast('尺寸已统一。原始切帧仍然保留，可随时还原。');}
